// 原Organization/人物控制全史后逐本次申请和答复核授权；批准与原Office失效事实必须真实紧邻。
#include "political_office_resignation_detail.hpp"
#include "resident/domains/organization/organization_office_history.hpp"
#include <map>
#include <set>
namespace hanmo::resident {
Status validate_political_office_resignation_sources(const PoliticalOfficeResignationContext& x){
 using namespace office_resignation_detail;auto valid=validate_political_office_resignation_catalog(x.common,x.common_catalog,x.politics_catalog,x.organization_catalog,x.successions,x.catalog);if(!valid.ok)return valid;
 if(x.state.version!=x.catalog.version||(x.state.version!=1&&x.state.version!=2)||x.state.requests.size()+x.state.answers.size()+x.state.withdrawals.size()>4096)return common_failure("InvalidPoliticalOfficeResignationState");if(!x.seat||!x.player_before)return common_failure("PoliticalOfficeResignationHistoricalReadersRequired");
 if((x.state.version==1&&(x.responses||!x.state.authored_origins.empty()))||(x.state.version==2&&!x.responses))return common_failure("OfficeResignationResponseVersionPairRequired");if(x.responses){valid=validate_political_office_resignation_responses(*x.responses,x.common_catalog,x.organization_catalog,x.successions,x.catalog);if(!valid.ok)return valid;}
 std::map<StableId,std::size_t> positions;std::size_t position=0;for(const auto& id:x.common.state().facts.order())positions[id]=position++;std::set<StableId> source_ids,ended;std::set<Integer> numbers;std::map<StableId,std::pair<Integer,Integer>> global_order;
 auto source=[&](const StableId& key,const StableId& id,const StableId& kind,const StableId& actor,Integer tick)->Status{auto n=political_office_resignation_fact_sequence(x.common,id,kind);if(key!=id||!n||!numbers.insert(*n).second||!source_ids.insert(id).second||!positions.count(id)||tick<0||tick>x.common.tick())return common_failure("PoliticalOfficeResignationFactSourceRequired",id);global_order.emplace(id,std::make_pair(*n,tick));if(x.state.authored_origins.find(id)){if(kind!="political_office_resignation_answered"||!x.responses)return common_failure("OfficeResignationResponseOriginCoverageMismatch",id);auto v=validate_political_office_resignation_authored_source(x.common,x.organizations,x.organization_catalog,x.state,*x.responses,id,x.player_before);if(!v.ok)return v;}else {auto p=x.player_before(tick,id);if(!p.ok)return {false,{},p.error};if(p.value!=actor)return common_failure("PoliticalOfficeResignationHistoricalPlayerMismatch",id);}return person_before(x,actor,tick,id);};
 Integer previous=0,last_tick=-1;std::size_t prior_position=0;
 for(const auto& row:x.state.requests.rows()){
  const auto& r=row.second;valid=source(row.first,r.id,"political_office_resignation_requested",r.actor_id,r.tick);if(!valid.ok)return valid;const auto number=*political_office_resignation_fact_sequence(x.common,r.id,"political_office_resignation_requested");if(number<=previous||r.tick<last_tick||(previous&&positions.at(r.id)<=prior_position))return common_failure("PoliticalOfficeResignationRequestOrderMismatch",r.id);previous=number;last_tick=r.tick;prior_position=positions.at(r.id);
  const auto* p=x.catalog.policies.find(r.policy_id);const auto* j=p?x.politics_catalog.jurisdictions.find(p->jurisdiction_id):nullptr;const auto* head=p?x.successions.policies.find(p->approval_succession_policy_id):nullptr;
  if(!p||!j||!head||r.office_id!=j->office_id||r.organization_id!=j->political_organization_id||r.approver_office_id!=head->leader_office_id||r.actor_id==r.approver_actor_id||r.jurisdiction_revision!=0||j->revision!=0||r.tick>2147483647-p->response_ticks||r.response_until!=r.tick+p->response_ticks)return common_failure("PoliticalOfficeResignationRequestMismatch",r.id);
  valid=holder_before(x,r.office_id,r.actor_id,r.office_epoch,r.tick,r.id);if(!valid.ok)return valid;valid=holder_before(x,r.approver_office_id,r.approver_actor_id,r.approver_epoch,r.tick,r.id);if(!valid.ok)return valid;valid=person_before(x,r.approver_actor_id,r.tick,r.id);if(!valid.ok)return valid;valid=grant(x,*p,r.tick);if(!valid.ok)return valid;valid=x.seat(*p,r.tick,r.id);if(!valid.ok)return valid;
  // 同任期旧申请须先终结或过期；后来的终结不能倒填先前第二次申请。
  for(const auto& earlier:x.state.requests.rows()){
   const auto& old=earlier.second;if(old.id==r.id)break;if(old.office_id!=r.office_id||old.office_epoch!=r.office_epoch||r.tick>=old.response_until)continue;bool closed_before=false;
   for(const auto& answer:x.state.answers.rows())if(answer.second.request_fact_id==old.id&&before(x.common,answer.first,r.id))closed_before=true;
   for(const auto& withdrawn:x.state.withdrawals.rows())if(withdrawn.second.request_fact_id==old.id&&before(x.common,withdrawn.first,r.id))closed_before=true;
   if(!closed_before)return common_failure("PoliticalOfficeResignationAlreadyPending",r.id);
  }
 }
 auto end=[&](const StableId& id,const StableId& request,Integer tick)->Outcome<const PoliticalOfficeResignationRequest*>{const auto* r=x.state.requests.find(request);const auto* h=x.common.state().facts.find(id);const auto a=h?political_office_resignation_fact_sequence(x.common,id,h->kind):std::nullopt;const auto b=r?political_office_resignation_fact_sequence(x.common,r->id,"political_office_resignation_requested"):std::nullopt;if(!r||!a||!b||*b>=*a||!before(x.common,r->id,id)||tick<r->tick||tick>=r->response_until||!ended.insert(request).second)return {false,nullptr,common_failure("PoliticalOfficeResignationCloseMismatch",id).error};return {true,r,{}};};
 previous=0;last_tick=-1;prior_position=0;
 for(const auto& row:x.state.answers.rows()){
  const auto& a=row.second;valid=source(row.first,a.id,"political_office_resignation_answered",a.actor_id,a.tick);if(!valid.ok)return valid;const auto number=*political_office_resignation_fact_sequence(x.common,a.id,"political_office_resignation_answered");if(number<=previous||a.tick<last_tick||(previous&&positions.at(a.id)<=prior_position))return common_failure("PoliticalOfficeResignationAnswerOrderMismatch",a.id);previous=number;last_tick=a.tick;prior_position=positions.at(a.id);auto request=end(a.id,a.request_fact_id,a.tick);if(!request.ok)return {false,{},request.error};const auto& r=*request.value;const auto& p=*x.catalog.policies.find(r.policy_id);
  if(a.actor_id!=r.approver_actor_id||a.approver_epoch!=r.approver_epoch||a.grant_id!=p.approval_grant_id)return common_failure("PoliticalOfficeResignationApproverMismatch",a.id);valid=holder_before(x,r.office_id,r.actor_id,r.office_epoch,a.tick,a.id);if(!valid.ok)return valid;valid=holder_before(x,r.approver_office_id,a.actor_id,a.approver_epoch,a.tick,a.id);if(!valid.ok)return valid;valid=person_before(x,r.actor_id,a.tick,a.id);if(!valid.ok)return valid;valid=grant(x,p,a.tick);if(!valid.ok)return valid;valid=x.seat(p,a.tick,a.id);if(!valid.ok)return valid;
  if(a.accepted){const auto* changed=x.organizations.facts.find(a.office_change_fact_id);const auto* h=x.common.state().facts.find(a.office_change_fact_id);const auto next=organization_instance_sequence(a.office_change_fact_id,"organization");if(!changed||changed->id!=a.office_change_fact_id||changed->kind!="organization_office_changed"||changed->organization_id!=r.organization_id||changed->office_id!=r.office_id||!changed->actor_id.empty()||changed->tick!=a.tick||changed->cause_fact_ids!=std::vector<StableId>{a.id}||!h||h->id!=changed->id||h->kind!=changed->kind||h->domain!="organization"||!next||number==std::numeric_limits<Integer>::max()||*next!=number+1||!positions.count(changed->id)||positions.at(changed->id)!=positions.at(a.id)+1||r.office_epoch==std::numeric_limits<Integer>::max()||a.vacant_office_epoch!=r.office_epoch+1)return common_failure("PoliticalOfficeResignationActualVacancyRequired",a.id);
  }else if(!a.office_change_fact_id.empty()||a.vacant_office_epoch!=0)return common_failure("PoliticalOfficeResignationRefusalChangedOffice",a.id);
 }
 previous=0;last_tick=-1;prior_position=0;
 for(const auto& row:x.state.withdrawals.rows()){
  const auto& w=row.second;valid=source(row.first,w.id,"political_office_resignation_withdrawn",w.actor_id,w.tick);if(!valid.ok)return valid;const auto number=*political_office_resignation_fact_sequence(x.common,w.id,"political_office_resignation_withdrawn");if(number<=previous||w.tick<last_tick||(previous&&positions.at(w.id)<=prior_position))return common_failure("PoliticalOfficeResignationWithdrawalOrderMismatch",w.id);previous=number;last_tick=w.tick;prior_position=positions.at(w.id);auto request=end(w.id,w.request_fact_id,w.tick);if(!request.ok)return {false,{},request.error};if(w.actor_id!=request.value->actor_id)return common_failure("PoliticalOfficeResignationApplicantRequired",w.id);
 }
 for(const auto& row:x.common.state().facts.rows()){const auto& f=row.second;const bool kind=f.kind=="political_office_resignation_requested"||f.kind=="political_office_resignation_answered"||f.kind=="political_office_resignation_withdrawn";if((kind||f.domain==political_office_resignation_module)&&(!kind||f.domain!=political_office_resignation_module||!source_ids.count(row.first)))return common_failure("PoliticalOfficeResignationPayloadRequired",row.first);}
 // 三表共同遵守原分配序，终结头不得移到数值较早的第二申请之前。
 previous=0;last_tick=-1;for(const auto& id:x.common.state().facts.order()){auto found=global_order.find(id);if(found==global_order.end())continue;if(found->second.first<=previous||found->second.second<last_tick)return common_failure("PoliticalOfficeResignationGlobalSourceOrderMismatch",id);previous=found->second.first;last_tick=found->second.second;}
 for(const auto& row:x.organizations.facts.rows())for(const auto& cause:row.second.cause_fact_ids){if(x.state.requests.find(cause)||x.state.withdrawals.find(cause))return common_failure("PoliticalOfficeResignationUnapprovedOfficeChange",row.first);if(const auto* answer=x.state.answers.find(cause);answer&&(!answer->accepted||row.first!=answer->office_change_fact_id))return common_failure("PoliticalOfficeResignationUnapprovedOfficeChange",row.first);}
 for(const auto& origin:x.state.authored_origins.rows())if(!x.state.answers.find(origin.first)||!source_ids.count(origin.first))return common_failure("OfficeResignationResponseOriginCoverageMismatch",origin.first);
 return common_success();
}
}
